 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    out = [row[:] for row in grid]

    # Collect maximal diagonal runs whose outward continuation has exactly
    # one clear side. Existing colored cells and the edge stop a ray.
    runs = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) < 2:
                    continue
                ends = []
                for er, ec, vr, vc in (
                    (cells[0][0] - dr, cells[0][1] - dc, -dr, -dc),
                    (cells[-1][0] + dr, cells[-1][1] + dc, dr, dc),
                ):
                    is_open = 0 <= er < h and 0 <= ec < w and grid[er][ec] == bg
                    ends.append((is_open, er, ec, vr, vc))
                if sum(x[0] for x in ends) == 1:
                    e = next(x for x in ends if x[0])
                    runs.append({'color': color, 'cells': cells,
                                 'ray': (e[1], e[2], e[3], e[4])})

    # A boundary-starting diagonal can be part of the given motif rather
    # than an unfinished ray when another independent ray is present.
    if len(runs) > 1:
        runs = [run for run in runs if run['cells'][0][0] != 0]

    # In an alternating 2x2 crossing motif, continue the longer diagonal
    # streak and leave the shorter crossing streak unchanged.
    rejected = set()
    for i, a in enumerate(runs):
        for j in range(i + 1, len(runs)):
            b = runs[j]
            if a['color'] == b['color'] or len(a['cells']) == len(b['cells']):
                continue
            ca, cb = a['color'], b['color']
            crossing = False
            for rr in range(h - 1):
                for cc in range(w - 1):
                    block = (grid[rr][cc], grid[rr][cc+1],
                             grid[rr+1][cc], grid[rr+1][cc+1])
                    if block == (ca, cb, cb, ca) or block == (cb, ca, ca, cb):
                        crossing = True
                        break
                if crossing:
                    break
            if crossing:
                rejected.add(i if len(a['cells']) < len(b['cells']) else j)

    for i, run in enumerate(runs):
        if i in rejected:
            continue
        r, c, dr, dc = run['ray']
        while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
            out[r][c] = run['color']
            r += dr
            c += dc
    return out


