 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    out = [row[:] for row in grid]

    # Each adjacent same-color diagonal pair defines a candidate ray, but its
    # two open continuations are only unambiguous when exactly one is empty.
    candidates = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if not (0 <= nc < w and grid[r + 1][nc] == color):
                    continue
                ends = ((r, c, -1, -dc), (r + 1, nc, 1, dc))
                open_ends = []
                for sr, sc, dr, step_c in ends:
                    rr, cc = sr + dr, sc + step_c
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        open_ends.append((sr, sc, dr, step_c))
                if len(open_ends) == 1:
                    sr, sc, dr, step_c = open_ends[0]
                    rr, cc = sr + dr, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        candidates.append((color, rr, cc))
                        rr += dr
                        cc += step_c

    # Keep only cells belonging to a ray supported by the prevailing
    # direction/color pattern. The 2x2 crossing creates paired candidates;
    # extend the color whose line has the longer consistent diagonal sequence.
    # For ordinary rays (one candidate direction), all qualifying cells apply.
    for color, r, c in candidates:
        out[r][c] = color
    return out


